/// <summary>
/// The <c>AVAProcessGuideBackEnabledNavigationAgentFactory</c> is a factory class that is responsible for creating <c>AVAProcessGuideBackEnabledNavigationAgent</c> objects.
/// </summary>
class AVAProcessGuideBackEnabledNavigationAgentFactory extends ProcessGuideNavigationAgentAbstractFactory
{
    private ProcessGuideNavigationRouteReversible navigationRoute;

}

Method.Source:
public final ProcessGuideNavigationAgent createNavigationAgent(ProcessGuideINavigationAgentCreationParameters _parameters)
{
    ProcessGuideNavigationAgentCreationParameters creationParameters = _parameters as ProcessGuideNavigationAgentCreationParameters;

    if (!creationParameters)
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }

    if (!navigationRoute)
    {
        navigationRoute = creationParameters.controller.parmNavigationRoute() as ProcessGuideNavigationRouteReversible;
        if (!navigationRoute)
        {
            throw error(Error::wrongUseOfFunction(funcName()));
        }
    }

    return new AVAProcessGuideBackEnabledNavigationAgent(navigationRoute, creationParameters.stepName, creationParameters.controller);
}
